import { useAppStore } from "@/store";
import { Card } from "@/shared/ui/data/Card";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import type { ThemeMode } from "@/features/settings/lib/appearance";

/** Settings → General: dark or light.
 *
 *  THE STORE, NOT localStorage. This card used to own the whole setting — it wrote `bsc-theme` to
 *  localStorage and set `data-theme` from its own `useEffect` — which meant the theme was applied
 *  when THIS CARD MOUNTED and at no other time. Every launch came up dark until you navigated to
 *  Settings → General, while the hint below claimed "Persisted across restarts". Nothing else in the
 *  app read the key: zero hits across src/, index.html, src-tauri/ and the record store.
 *
 *  Now it is a store field like `accent` beside it, applied by `useAppBoot`, written through to
 *  session.db by `USER_SETTING_KINDS` — which is also what carries it to the phone. */
export function ThemeCard() {
  const theme = useAppStore((s) => s.theme);
  const setTheme = useAppStore((s) => s.setTheme);

  return (
    <Card title="Theme">
      <Row gap={8} align="stretch">
        {(["dark", "light"] as const satisfies readonly ThemeMode[]).map((t) => (
          // eslint-disable-next-line no-restricted-syntax -- bespoke accent pill toggle with custom on-state bg/color; not the .btn family, SegmentedControl's .seg CSS would change rendering
          <button
            key={t}
            className="mono"
            aria-pressed={theme === t}
            onClick={() => setTheme(t)}
            style={{
              padding: "6px 18px", borderRadius: 6, cursor: "pointer",
              fontSize: 11.5,
              background: theme === t ? "var(--accent)" : "var(--bg-elev)",
              color: theme === t ? "#fff" : "var(--fg-muted)",
              border: "1px solid " + (theme === t ? "transparent" : "var(--border-soft)"),
            }}
          >{t.charAt(0).toUpperCase() + t.slice(1)}</button>
        ))}
      </Row>
      <Box className="hint" style={{ marginTop: 10 }}>
        Applied at launch and carried to a paired phone. Light mode moves all surfaces to the token
        layer — a few hardcoded terminal palette values may still appear dark.
      </Box>
    </Card>
  );
}
